+}
+
+impl From<WhitenoiseMessageUpdate> for MessageUpdate {
+    fn from(update: WhitenoiseMessageUpdate) -> Self {
+        (&update).into()
+    }
+}
+
+#[frb]
+pub async fn send_message_to_group(
